<script setup lang="ts">
import type { ConnectedMailbox, MailboxMessage } from '../services/connectedMailboxApi'
import {validateReviewedMailboxDraft} from '../../supabase/functions/_shared/mailboxBookingDraft'
const props=defineProps<{workspaceId:string;locale:'es'|'en';artists:Array<{id:string;stage_name:string}>}>()
const emit=defineEmits<{created:[bookingId:string]}>()
const api=useConnectedMailbox(),es=computed(()=>props.locale==='es')
const connections=ref<ConnectedMailbox[]>([]),connectionId=ref(''),artistId=ref(''),messages=ref<MailboxMessage[]>([]),selected=ref<MailboxMessage|null>(null),loading=ref(false),busy=ref(false),error=ref(''),hasMore=ref(false)
const analysisConsent=ref(false),selectedConsent=ref(false),analyzingSelected=ref(false),analyzed=ref(false),showAll=ref(false)
const review=reactive({eventDate:'',startTime:'',endTime:'',venue:'',city:'',amount:'',currency:'',contactName:'',contactPhone:'',eventTimezone:''})
const draftWarnings=ref<string[]>([])
function prepareReview(message:MailboxMessage){const d=message.classification?.draft;Object.assign(review,{eventDate:d?.eventDate||'',startTime:d?.startTime||'',endTime:d?.endTime||'',venue:d?.venue||'',city:d?.city||'',amount:d?.offerAmountMinor==null?'':String(d.offerAmountMinor/100),currency:d?.currency||'',contactName:message.senderName||message.from,contactPhone:d?.contactPhone||'',eventTimezone:Intl.DateTimeFormat().resolvedOptions().timeZone});draftWarnings.value=d?.warnings||[];const name=d?.artistName?.trim().toLocaleLowerCase();const matches=name?props.artists.filter(a=>a.stage_name.trim().toLocaleLowerCase()===name):[];artistId.value=matches.length===1?matches[0]!.id:props.artists.length===1?props.artists[0]!.id:''}
const shownMessages=computed(()=>analyzed.value&&!showAll.value?messages.value.filter(m=>m.classification?.kind!=='other'):showAll.value?messages.value:[])
let generation=0
function analysisError(e:any){if(e?.message==='mailbox_ai_quota_exhausted')return es.value?'El análisis con IA está pausado porque se ha agotado su cuota. Puedes crear la solicitud manualmente.':'AI analysis is paused because its quota is exhausted. You can create the request manually.';if(e?.message==='mailbox_ai_rate_limit')return es.value?'La IA ha alcanzado un límite temporal. Prueba más tarde o crea la solicitud manualmente.':'AI has reached a temporary limit. Try later or create the request manually.';if(e?.message==='mailbox_analysis_rate_limit')return es.value?'Espera un minuto antes de volver a analizar.':'Wait one minute before analyzing again.';if(e?.message==='mailbox_ai_not_configured')return es.value?'El análisis con IA todavía no está configurado. Puedes crear la solicitud manualmente.':'AI analysis is not configured yet. You can create the request manually.';if(e?.message==='mailbox_ai_unavailable')return es.value?'El servicio de IA no está disponible. Puedes crear la solicitud manualmente y probar el análisis más tarde.':'The AI service is unavailable. You can create the request manually and try analysis later.';return es.value?'No se pudo analizar este correo. Inténtalo de nuevo.':'This email could not be analyzed. Try again.'}

async function load(analyze=false){const turn=++generation;loading.value=true;error.value='';messages.value=[];selected.value=null
 try {const status=await api.status(props.workspaceId);if(turn!==generation)return;connections.value=status.connections.filter(c=>c.status==='connected');connectionId.value=connections.value.some(c=>c.id===connectionId.value)?connectionId.value:connections.value[0]?.id||'';if(connectionId.value){const result=analyze&&analysisConsent.value?await api.classify(props.workspaceId,connectionId.value):await api.recent(props.workspaceId,connectionId.value);analyzed.value=analyze&&analysisConsent.value;if(turn===generation){messages.value=result.messages;hasMore.value=result.hasMore}}}
 catch(e:any){if(turn===generation)error.value=e?.message==='mailbox_analysis_rate_limit'?(es.value?'Espera un minuto antes de volver a analizar.':'Wait one minute before analyzing again.'):es.value?'No se pudieron cargar los correos. Inténtalo de nuevo.':'Emails could not be loaded. Try again.'}
 finally{if(turn===generation)loading.value=false}}
async function analyzeSelected(){if(!selected.value||!selectedConsent.value||busy.value||loading.value)return;const turn=generation,id=selected.value.id;busy.value=true;analyzingSelected.value=true;error.value='';try{const result=await api.classify(props.workspaceId,connectionId.value,id);if(turn!==generation)return;const message=result.messages.find(m=>m.id===id);if(!message)throw new Error('missing_analysis');messages.value=messages.value.map(m=>m.id===id?message:m);if(selected.value?.id===id){selected.value=message;prepareReview(message)}}catch(e:any){if(turn===generation)error.value=analysisError(e)}finally{analyzingSelected.value=false;if(turn===generation)busy.value=false}}
watch(()=>selected.value?.id,()=>{selectedConsent.value=false;if(selected.value)prepareReview(selected.value)})
async function importMessage(){if(!selected.value||!artistId.value||busy.value)return;busy.value=true;error.value='';try{const amount=review.amount.trim();const reviewed=validateReviewedMailboxDraft({eventDate:review.eventDate||null,startTime:review.startTime||null,endTime:review.endTime||null,venue:review.venue.trim()||null,city:review.city.trim()||null,offerAmountMinor:amount===''?null:Math.round(Number(amount)*100),currency:review.currency.trim().toUpperCase()||null,contactName:review.contactName.trim(),contactPhone:review.contactPhone.trim()||null,eventTimezone:review.startTime||review.endTime?review.eventTimezone.trim()||null:null});const result=await api.importMessage(props.workspaceId,connectionId.value,selected.value.id,artistId.value,undefined,reviewed);emit('created',result.bookingId);await load(analyzed.value)}catch(e:any){error.value=e?.message==='booking_time_requires_date'?(es.value?'Añade la fecha completa para guardar el horario.':'Add the full date to save the schedule.'):e?.message==='booking_currency_required'?(es.value?'Indica la moneda del presupuesto.':'Specify the offer currency.'):e?.message==='invalid_booking_draft'?(es.value?'Revisa los datos: fecha, horario, importe y contacto deben ser válidos.':'Check the date, times, amount and contact details.'):es.value?'No se pudo incorporar el correo. Comprueba el artista e inténtalo de nuevo.':'Could not attach this email. Check the artist and retry.'}finally{busy.value=false}}
watch(()=>props.workspaceId,()=>{analysisConsent.value=false;analyzed.value=false;showAll.value=false;void load()},{immediate:true})
watch(()=>props.artists,artists=>{artistId.value=artists.length===1?artists[0]!.id:''},{immediate:true})
onBeforeUnmount(()=>generation++)
</script>
<template>
<section v-if="connections.length || error" class="mailbox-requests" aria-labelledby="mailbox-requests-title">
 <header><div><h2 id="mailbox-requests-title">{{es?'Solicitudes por correo':'Email enquiries'}}</h2><p>{{es?'Solo tú ves estos correos. Al crear una solicitud, su conversación se comparte con tu workspace.':'Only you can see these emails. Creating a request shares its conversation with your workspace.'}}</p></div><button type="button" :disabled="loading||busy" @click="load(analyzed)">{{es?'Actualizar':'Refresh'}}</button></header>
 <label v-if="connections.length>1">{{es?'Buzón':'Mailbox'}}<select v-model="connectionId" :disabled="busy" @change="load(analyzed)"><option v-for="c in connections" :key="c.id" :value="c.id">{{c.email}}</option></select></label>
 <p class="mailbox-requests__hint">{{es?'Prueba de correo: últimos 20 mensajes de los últimos 7 días. La importación automática todavía no está activa.':'Email pilot: latest 20 messages from the last 7 days. Automatic import is not active yet.'}}</p>
 <div class="mailbox-requests__analysis"><label><input v-model="analysisConsent" type="checkbox" :disabled="busy||loading">{{es?'Autorizo enviar a Groq el asunto y hasta 2.500 caracteres de cada correo reciente para detectar solicitudes. No se envían adjuntos ni se responde automáticamente.':'I authorize sending Groq the subject and up to 2,500 characters of each recent email to detect enquiries. No attachments are sent and no automatic replies are issued.'}}</label><button type="button" :disabled="!analysisConsent||loading||busy" @click="load(true)">{{es?'Detectar solicitudes':'Detect enquiries'}}</button><button type="button" :disabled="loading||busy" @click="showAll=!showAll">{{showAll?(es?'Ocultar otros correos':'Hide other emails'):(es?'Ver todos los correos de prueba':'View all pilot emails')}}</button></div>
 <p v-if="loading" role="status">{{es?'Cargando correos…':'Loading emails…'}}</p>
 <div v-else class="mailbox-requests__layout"><div class="mailbox-requests__list"><button :disabled="busy" v-for="message in shownMessages" :key="message.id" type="button" :aria-pressed="selected?.id===message.id" @click="selected=message"><span>{{message.senderName}}</span><strong>{{message.subject}}</strong><small v-if="message.classification">{{message.classification.kind==='booking'?(es?'Posible solicitud':'Possible enquiry'):message.classification.kind==='review'?(es?'Por revisar':'Review'):(es?'Otro correo':'Other email')}} · {{message.classification.reason}}</small><small>{{new Date(message.date).toLocaleDateString(locale)}}</small></button><p v-if="!shownMessages.length">{{analyzed?(es?'No se han detectado posibles solicitudes en esta selección. Puedes revisar los demás correos.':'No possible enquiries were detected in this selection. You can review other emails.'):(es?'Activa el análisis para separar las posibles solicitudes del resto del correo.':'Enable analysis to separate possible enquiries from other email.')}}</p></div>
 <article v-if="selected"><h3>{{selected.subject}}</h3><p>{{selected.from}}</p><p class="mailbox-requests__body">{{selected.body}}</p><div class="mailbox-requests__analysis"><label><input v-model="selectedConsent" type="checkbox" :disabled="busy||loading">{{es?'Autorizo analizar solo este correo con Groq: asunto y hasta 2.500 caracteres, sin adjuntos.':'I authorize analyzing only this email with Groq: subject and up to 2,500 characters, without attachments.'}}</label><button type="button" :disabled="!selectedConsent||busy||loading" @click="analyzeSelected">{{analyzingSelected?(es?'Analizando…':'Analyzing…'):(es?'Analizar solo este correo':'Analyze only this email')}}</button><p v-if="selected.classification" role="status">{{selected.classification.kind==='booking'?(es?'Posible solicitud':'Possible enquiry'):selected.classification.kind==='review'?(es?'Por revisar':'Review'):(es?'Otro correo':'Other email')}} · {{selected.classification.reason}}</p></div><fieldset class="mailbox-requests__draft" :disabled="busy||loading"><legend>{{es?'Datos de la solicitud':'Enquiry details'}}</legend><p>{{es?'Revisa las sugerencias antes de guardar. Crear una solicitud no confirma ninguna actuación ni envía una respuesta.':'Review the suggestions before saving. Creating an enquiry does not confirm a performance or send a reply.'}}</p><p v-for="warning in draftWarnings" :key="warning" class="mailbox-requests__warning">{{warning}}</p><div class="mailbox-requests__fields"><label>{{es?'Nombre del contacto':'Contact name'}}<input v-model="review.contactName" maxlength="200" autocomplete="off"></label><label>Email<input :value="selected.from" type="email" readonly></label><label>{{es?'Teléfono · opcional':'Phone · optional'}}<input v-model="review.contactPhone" type="tel" maxlength="200"></label><label>{{es?'Fecha':'Date'}}<input v-model="review.eventDate" type="date"></label><label>{{es?'Hora de inicio':'Start time'}}<input v-model="review.startTime" type="time"></label><label>{{es?'Hora de fin':'End time'}}<input v-model="review.endTime" type="time"></label><label v-if="review.startTime||review.endTime">{{es?'Zona horaria · revisa antes de guardar':'Timezone · review before saving'}}<input v-model="review.eventTimezone" maxlength="80" placeholder="Europe/Madrid"></label><label>{{es?'Sala / lugar':'Venue'}}<input v-model="review.venue" maxlength="200"></label><label>{{es?'Ciudad':'City'}}<input v-model="review.city" maxlength="200"></label><label>{{es?'Presupuesto propuesto':'Proposed offer'}}<input v-model="review.amount" type="number" min="0" step="0.01" inputmode="decimal"></label><label>{{es?'Moneda':'Currency'}}<input v-model="review.currency" maxlength="3" placeholder="EUR"></label></div><p>{{es?'El contacto se guarda con el email del remitente. Si el hilo ya está incorporado, abrimos su solicitud conservando los datos existentes.':'The contact is saved with the sender email. If this thread is already linked, we open its enquiry and preserve existing details.'}}</p></fieldset><label>{{es?'Artista':'Artist'}}<select v-model="artistId" :aria-label="es?'Artista':'Artist'" :disabled="busy"><option value="">{{es?'Selecciona un artista':'Select an artist'}}</option><option v-for="artist in artists" :key="artist.id" :value="artist.id">{{artist.stage_name}}</option></select></label><button class="mailbox-requests__create" type="button" :disabled="busy||!artistId" @click="importMessage">{{busy&&!analyzingSelected?(es?'Creando…':'Creating…'):(es?'Crear solicitud y continuar el hilo':'Create request and continue thread')}}</button></article></div>
 <p v-if="hasMore" class="mailbox-requests__hint">{{es?'Hay más correos en tu buzón; esta prueba muestra una selección reciente.':'More emails exist in your mailbox; this pilot displays a recent selection.'}}</p>
 <p v-if="error" class="mailbox-requests__error" role="alert">{{error}}</p>
</section>
</template>
<style scoped>
.mailbox-requests__draft{margin:18px 0;padding:16px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-panel);min-width:0}.mailbox-requests__draft legend{font-size:13px;color:var(--cue-text);padding:0 6px}.mailbox-requests__fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.mailbox-requests__fields input{box-sizing:border-box;min-width:0;width:100%;min-height:44px;padding:8px 10px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-control);background:var(--cue-raised);color:var(--cue-text);font:inherit;color-scheme:dark}.mailbox-requests__fields input:focus-visible{outline:2px solid var(--cue-accent);outline-offset:3px}.mailbox-requests__fields input[readonly]{color:var(--cue-muted)}.mailbox-requests__warning{border-left:3px solid #d9a84e;padding:8px 12px;background:color-mix(in srgb,#d9a84e 8%,transparent)}@media(max-width:680px){.mailbox-requests__fields{grid-template-columns:1fr}}
.mailbox-requests{padding:20px;margin:0 0 24px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-panel);background:var(--cue-surface)}header{display:flex;align-items:start;justify-content:space-between;gap:16px}h2{font-size:17px;margin:0 0 8px}h3{font-size:15px;overflow-wrap:anywhere}p{font-size:12px;line-height:1.5;color:var(--cue-muted)}.mailbox-requests__analysis{display:flex;flex-wrap:wrap;gap:10px;margin:16px 0}.mailbox-requests__analysis label{display:flex;align-items:start;font-size:12px;line-height:1.5;flex-basis:100%}.mailbox-requests__analysis input{accent-color:var(--cue-accent);width:18px;height:18px;flex-shrink:0}
button,select{min-height:44px;padding:8px 12px;border:1px solid var(--cue-border);border-radius:var(--cue-radius-control);background:var(--cue-raised);color:var(--cue-text);font-size:12px;cursor:pointer}button:disabled{opacity:.5;cursor:default}button:focus-visible,select:focus-visible{outline:2px solid var(--cue-accent);outline-offset:3px}.mailbox-requests__layout{display:grid;grid-template-columns:minmax(200px,1fr) minmax(0,1.5fr);gap:20px}.mailbox-requests__list{display:grid;align-content:start;gap:6px;max-height:430px;overflow:auto}.mailbox-requests__list button{display:grid;gap:5px;text-align:left;overflow-wrap:anywhere}.mailbox-requests__list button[aria-pressed=true]{border-color:var(--cue-accent)}small,span{font-size:11px;color:var(--cue-muted)}article{min-width:0}.mailbox-requests__body{white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto;color:var(--cue-text)}label{display:grid;gap:6px;font-size:12px}.mailbox-requests__create{margin-top:14px;background:var(--cue-accent);color:#080808}.mailbox-requests__error{border-left:3px solid #e65e6a;padding:12px;background:color-mix(in srgb,#e65e6a 8%,transparent)}.mailbox-requests__hint{font-size:11px}@media(max-width:680px){.mailbox-requests{padding:14px}.mailbox-requests__layout{grid-template-columns:1fr}header{flex-wrap:wrap}.mailbox-requests__list{max-height:240px}}
</style>
